advanced.code:
// +page.js
export const ssr = false;

// Often paired with browser-only logic in the component

// in load
export async function load({ fetch, depends }) {
  depends('app:todos');
  const res = await fetch('/api/todos');
  return { todos: await res.json() };
}

// after a mutation
import { invalidate } from '$app/navigation';
await invalidate('app:todos');

// parent
import { setContext } from 'svelte';
setContext('editor', createEditorState());

// child
import { getContext } from 'svelte';
const editor = getContext('editor');

let items = [{ done: false }];

function toggle() {
  items[0].done = !items[0].done;
  items = items; // force reassignment so update is scheduled
}

let controller;

async function search(q) {
  controller?.abort();
  controller = new AbortController();
  const res = await fetch(`/api/search?q=${q}`, {
    signal: controller.signal
  });
  results = await res.json();
}
